import os, subprocess, json

data = {}
for file in os.listdir("."):
    if file.endswith(".pdf"):
        res = subprocess.run(["pdfimages", "-list", file], capture_output=True, text=True)
        lines = res.stdout.strip().split("\n")[2:]
        pages = []
        for line in lines:
            parts = line.split()
            if len(parts) >= 12:
                pages.append({
                    "page": int(parts[0]),
                    "type": parts[2],
                    "width": int(parts[3]),
                    "height": int(parts[4]),
                    "color_space": parts[5],
                    "bpc": int(parts[7]),
                    "is_flattened_1bit": parts[5] == "gray" and parts[7] == "1"
                })
        data[file] = {
            "total_images": len(pages),
            "multiple_layers_detected": len(pages) > 2, 
            "pages": pages
        }

with open("mapeo_estructural.json", "w") as f:
    json.dump(data, f, indent=4)
print(json.dumps(data, indent=4))
'

