import csv, os, hashlib

file_path = '/home/andrea-zabala-c/Music/archivo para anzeca1.csv'
base_dir = '/home/andrea-zabala-c/Desktop/DELEGADOS_UNZIPPED/media/andrea-zabala-c/D A T A1/delegados/Delegados_21_06_2026'

def get_hash(filepath):
    sha256 = hashlib.sha256()
    with open(filepath, 'rb') as f:
        for block in iter(lambda: f.read(4096), b''):
            sha256.update(block)
    return sha256.hexdigest()

with open(file_path, newline='') as f:
    rows = list(csv.DictReader(f))

csv_data = {}
for r in rows:
    filename = r['archivo']
    csv_data[filename] = {
        'antiguos': r['hash_antiguos_reportado'],
        'ahora': r['hash_ahora_reportado'],
        'transmision': r['hash_transmision_reportado']
    }

results = {'antiguos': 0, 'ahora': 0, 'transmision': 0, 'desconocido': 0, 'no_encontrado': 0}
desconocidos = []

for filename, hashes in csv_data.items():
    filepath = os.path.join(base_dir, filename)
    if not os.path.exists(filepath):
        results['no_encontrado'] += 1
        continue

    file_hash = get_hash(filepath)

    if file_hash == hashes['antiguos']:
        results['antiguos'] += 1
    elif file_hash == hashes['ahora']:
        results['ahora'] += 1
    elif file_hash == hashes['transmision']:
        results['transmision'] += 1
    else:
        results['desconocido'] += 1
        desconocidos.append(filename)

print('=== RESULTADO DE LA COMPARACIÓN FORENSE DE HASHES ===')
print(f'Total archivos únicos procesados: {len(csv_data)}')
print(f'Coincide con hash ANTIGUOS (Versión original sin alterar): {results[\"antiguos\"]}')
print(f'Coincide con hash AHORA (Versión actual/corrompida): {results[\"ahora\"]}')
