print(f'NO COINCIDE con ninguno (Desconocido / Mutado): {results[\"desconocido\"]}')
print(f'No encontrado en disco: {results[\"no_encontrado\"]}')

if desconocidos:
    print('\nArchivos con hash desconocido:')
    for d in desconocidos[:5]: print(' -', d)
