import csv

def find_redirects(csv_path):
    # Load all original payloads
    original_to_mesa = {}
    with open(csv_path, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            archivo = row['archivo']
            payload_izq = row['qr_payloads_izq']
            if payload_izq:
                # Sometimes there are multiple separated by |
                for p in payload_izq.split('|'):
                    original_to_mesa[p.strip()] = archivo

    # Now check for redirects
    redirects = []
    with open(csv_path, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            archivo = row['archivo']
            payload_der = row['qr_payloads_der']
            if payload_der:
                for p in payload_der.split('|'):
                    p = p.strip()
                    if p in original_to_mesa and original_to_mesa[p] != archivo:
                        redirects.append(f"Acta {archivo} fue redirigida a {original_to_mesa[p]}")

    print(f"Total redirecciones encontradas dentro del CSV: {len(redirects)}")
    for r in redirects:
        print(r)

if __name__ == '__main__':
