import csv
import os
import json

input_dir = '/home/andrea-zabala-c/Desktop/repo_github_comparacion/02_ANALISIS/SESION_02_ESTADISTICA_Y_BENFORD/ANALISIS_FORENSE_CLAVEROS_32_DEPARTAMENTOS/TOP_DEPARTAMENTOS_ANOMALOS'
output_html = '/home/andrea-zabala-c/Desktop/repo_github_comparacion/02_ANALISIS/SESION_02_ESTADISTICA_Y_BENFORD/dashboard_campanas_gauss.html'

files = [f for f in os.listdir(input_dir) if f.endswith('.csv')]
charts_data = []

def create_histogram(data, bins=30):
    if not data: return [], []
    min_val, max_val = 0, 400
    bin_size = max_val / bins
    counts = [0] * bins
    labels = [int(i * bin_size) for i in range(bins)]
    for val in data:
        idx = min(int(val / bin_size), bins - 1)
        if idx >= 0:
            counts[idx] += 1
    return labels, counts

for file in files:
    filepath = os.path.join(input_dir, file)
    dpto_name = file.replace('_mesas_anomalas.csv', '').replace('_', ' ')

    candidato_1 = []
    candidato_2 = []

    with open(filepath, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            try:
                # Intercambiamos los valores base de la base de datos para corregir el mapeo
                candidato_1.append(int(row['Votos_Espriella'])) 
                candidato_2.append(int(row['Votos_Cepeda'])) 
            except:
                pass

    if not candidato_1:
        continue

    labels, counts_c1 = create_histogram(candidato_1)
    _, counts_c2 = create_histogram(candidato_2)

    charts_data.append({
        'title': f'Planchado Estadístico - {dpto_name}',
        'labels': labels,
        'candidato_1': counts_c1,
        'candidato_2': counts_c2
    })

html_content = f"""
<!DOCTYPE html>
<html lang="es">
<head>
    <meta charset="UTF-8">
    <title>Siguiendo la Anomalía PDF: El Rastro</title>
    <script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
    <script src="https://cdnjs.cloudflare.com/ajax/libs/PapaParse/5.3.2/papaparse.min.js"></script>
    <script type="module">
        import mermaid from 'https://cdn.jsdelivr.net/npm/mermaid@10/dist/mermaid.esm.min.mjs';
        mermaid.initialize({{ startOnLoad: true, theme: 'dark' }});
    </script>
    <style>
        body {{ background-color: #0f172a; color: white; font-family: 'Inter', sans-serif; padding: 40px; }}
        h1 {{ text-align: center; color: #38bdf8; font-size: 2.5em; text-transform: uppercase; letter-spacing: 2px; }}
        .subtitle {{ text-align: center; color: #94a3b8; margin-bottom: 50px; font-size: 1.2em; }}
        .mermaid-container {{ background: #1e293b; padding: 30px; border-radius: 15px; border: 1px solid #334155; margin-bottom: 60px; box-shadow: 0 10px 15px -3px rgba(0,0,0,0.3); }}
        .grid {{ display: grid; grid-template-columns: repeat(auto-fit, minmax(450px, 1fr)); gap: 30px; }}
        .chart-container {{ background: #1e293b; padding: 25px; border-radius: 15px; border: 1px solid #334155; box-shadow: 0 4px 6px -1px rgba(0,0,0,0.1); transition: transform 0.3s ease; }}
        .chart-container:hover {{ transform: translateY(-5px); border-color: #38bdf8; }}
        .upload-section {{ background: #0f172a; border: 2px dashed #38bdf8; padding: 40px; text-align: center; border-radius: 15px; margin-bottom: 60px; cursor: pointer; transition: background 0.3s; }}
        .upload-section:hover {{ background: #1e293b; }}
        #csv-upload {{ display: none; }}
        .upload-btn {{ background: #38bdf8; color: #0f172a; padding: 10px 20px; font-weight: bold; border-radius: 5px; cursor: pointer; font-size: 16px; border: none; }}
    </style>
</head>
<body>
    <h1>Siguiendo la Anomalía PDF</h1>
    <p class="subtitle">El rastro criptográfico del fraude: desde la inyección física hasta el aplastamiento estadístico.</p>

    <div class="upload-section" onclick="document.getElementById('csv-upload').click()">
        <h2 style="color: #38bdf8;">Auditoría Pública: Sube tu propia tabla de transmisión (.CSV)</h2>
        <p style="color: #cbd5e1;">Haz clic aquí o arrastra un archivo CSV para que el algoritmo procese los votos en tiempo real y dibuje la Campana de Gauss.</p>
        <button class="upload-btn">Subir Archivo CSV</button>
        <input type="file" id="csv-upload" accept=".csv" onchange="handleFileUpload(event)">
    </div>

    <div id="custom-chart-container" class="chart-container" style="display: none; margin-bottom: 60px; border-color: #facc15;">
        <h3 style="color: #facc15; text-align: center;">Resultados de tu Archivo:</h3>
        <canvas id="custom-chart"></canvas>
    </div>

    <div class="mermaid-container">
        <h2 style="color: #cbd5e1; text-align: center; margin-bottom: 30px;">El Rastro de la Alteración (Línea de Tiempo)</h2>
        <div class="mermaid" style="text-align: center;">
            graph TD
                classDef physical fill:#b45309,color:#fff,stroke:#fcd34d,stroke-width:2px;
