import os
import shutil

desktop_dir = '/home/andrea-zabala-c/Desktop'

# Definición de las carpetas destino
categorias = {
    'SCRIPTS_FORENSES': ['py'],
    'DOCUMENTOS_Y_REPORTES': ['md', 'txt', 'docx'],
    'EVIDENCIA_Y_DATOS': ['csv', 'zip', 'lock', 'count'],
    'PERSONAL_Y_ADMINISTRATIVO': [], # Manual routing for specific names
    'SOFTWARE_E_INSTALADORES': ['run', 'asc', 'desktop', 'swo']
}

# Carpetas y archivos a ignorar completamente (las bases del proyecto)
ignore_list = [
    'repo_github_comparacion', 'ENTREGABLES_FORENSES_E14', 
    'DELEGADOS_UNZIPPED', 'EXPEDIENTE_PERSONAL_Y_DENUNCIAS_ANDREA_ZABALA',
    'MUESTRA_LINEA_FRAUDE', 'REPORTES_POR_PAIS', 'REVELACION_CAPAS_OCULTAS',
    '.fr-ZvwKdz', 'New Folder', 'TO PRINT', 'actas', 'adjuntos_denuncia', 'anti', 'segundaVuelta'
]

# Crear directorios destino si no existen
for cat in categorias.keys():
    os.makedirs(os.path.join(desktop_dir, cat), exist_ok=True)

# Nombres específicos para la carpeta personal
personal_files_or_dirs = [
    'Facturas', 'FOTOS_MI_CUMPLE_ARTURIN', 
    'statement.pdf', 'statement (1).pdf', 'statement (2).pdf', 'Message.pdf',
    'video.txt'
]

# Recorrer el escritorio
for item in os.listdir(desktop_dir):
    if item in ignore_list or item in categorias.keys():
        continue

    src_path = os.path.join(desktop_dir, item)
    dest_path = None

    # 1. Routing manual (Personal/Administrativo)
    if item in personal_files_or_dirs:
        dest_path = os.path.join(desktop_dir, 'PERSONAL_Y_ADMINISTRATIVO', item)

    # 2. Extension routing para archivos
    elif os.path.isfile(src_path):
        ext = item.split('.')[-1].lower() if '.' in item else ''

        # PDFs que no sean los statement/Message asumo que son reportes
        if ext == 'pdf':
            dest_path = os.path.join(desktop_dir, 'DOCUMENTOS_Y_REPORTES', item)

        for cat, extensions in categorias.items():
            if ext in extensions:
                dest_path = os.path.join(desktop_dir, cat, item)
                break

        # Si no se enrutó pero es archivo, ponlo en Datos por defecto si no sabemos qué es (ej. sin extensión)
        if not dest_path:
            if 'Forensic_report' in item or 'Informe_forense' in item or 'global_executive_summary' in item:
                dest_path = os.path.join(desktop_dir, 'DOCUMENTOS_Y_REPORTES', item)
            else:
                dest_path = os.path.join(desktop_dir, 'EVIDENCIA_Y_DATOS', item)

    # Movemos el archivo o carpeta
    if dest_path:
        try:
            shutil.move(src_path, dest_path)
            print(f"Moved: {item} -> {os.path.basename(os.path.dirname(dest_path))}")
        except Exception as e:
            print(f"Failed to move {item}: {e}")

print("[*] Organización del escritorio completada exitosamente.")

